window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2c75cd220f275a54"]={"versions": [{"id": "FIG-2c75cd220f275a54", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt der AUTOSAR ECU Configuration Description (Werte-Ebene / <em>Values</em>).\n</li><li><strong>Architektur-Kontext:</strong> Definiert die formale Datenstruktur zur Ablage konkreter Parameterwerte (<code>ParameterValue</code>) innerhalb der Konfigurationsbäume (<code>Container</code>) für AUTOSAR-Basissoftware (BSW), RTE und System-Module. Es bildet die Instanzebene ab, die zur Konfigurationszeit (Design/Generate Time) befüllt und von BSW- und RTE-Codegeneratoren verarbeitet wird.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>Identifiable</code></strong> <em>(Metaklasse/Stereotyp)</em>: Basis-Metaklasse für alle eindeutig adressierbaren Artefakte (stellt u. a. <code>shortName</code> und UUID bereit).\n</li><li><strong><code>Container</code></strong> <em>(Spezialisierung von <code>Identifiable</code>)</em>:\n<ul class=\"fig-list\"><li>Strukturelle Kapselung logisch zusammengehöriger Parameter und Unterstrukturen.\n</li><li><strong>Beziehungen:</strong>\n<ul class=\"fig-list\"><li><em>Selbstreferenzielle Komposition:</em> <code>0..1</code> Container enthält <code>*</code> Sub-Container (<code>+subContainer</code>).\n</li><li><em>Komposition zu Werten:</em> <code>1</code> Container aggregiert <code>0..*</code> Parameterwerte (<code>+parameterValue</code>).\n</li></ul>\n</li></ul>\n</li><li><strong><code>ParameterValue</code></strong> <em>(abstrakte Basisklasse)</em>:\n<ul class=\"fig-list\"><li>Abstrakter Anker für alle typisierten Konfigurationsparameter.\n</li></ul>\n</li><li><strong>Typisierte Ableitungen von <code>ParameterValue</code>:</strong>\n<ul class=\"fig-list\"><li><strong><code>BooleanValue</code></strong>: Attribut <code>+ value: Boolean</code> (repräsentiert logische Schalter, Flags).\n</li><li><strong><code>IntegerValue</code></strong>: Attribut <code>+ value: Int</code> (ganzzahlige Werte wie Zähler, PDU-IDs, IDs, Puffergrößen).\n</li><li><strong><code>FloatValue</code></strong>: Attribut <code>+ value: Float</code> (Fließkommazahlen für Zeitkonstanten, physikalische Skalierungen).\n</li><li><strong><code>EnumerationValue</code></strong>: Attribut <code>+ value: String</code> (Textuelle Repräsentation des ausgewählten Literals).\n</li><li><strong><code>StringValue</code></strong>: Attribut <code>+ value: String</code> (Generische Zeichenketten, Pfade, Dateinamen).\n</li></ul>\n</li><li><strong>Spezialisierungskette für Symbol-Referenzen:</strong>\n<ul class=\"fig-list\"><li><strong><code>LinkerSymbolValue</code></strong> <em>(erbt von <code>StringValue</code>)</em>: Spezieller Bezeichner, der zur Link-Zeit gegen ein Symbol im Objektcode auflösbar sein muss.\n</li><li><strong><code>FunctionNameValue</code></strong> <em>(erbt von <code>LinkerSymbolValue</code>)</em>: Repräsentiert explizit einen C-Funktionsnamen (z. B. Entrypoints, Callbacks, Notifier).\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Laufzeit-Verhalten:</strong> Nicht zutreffend (statisches Konfigurations-Metamodell).\n</li><li><strong>Toolchain-/Generierungs-Zyklus:</strong>\n<ol class=\"fig-list\"><li><strong>Parsen:</strong> Der Konfigurationsgenerator liest den hierarchischen Container-Baum (<code>Container</code> → <code>subContainer</code>) aus der ARXML ein.\n</li><li><strong>Typauflösung:</strong> Instanzen von <code>ParameterValue</code> werden gegen die korrespondierende Parameter-Definition (<code>ParameterDef</code>) validiert (Wertebereichs- und Typprüfung).\n</li><li><strong>Artefakt-Generierung:</strong> \n<ul class=\"fig-list\"><li><code>BooleanValue</code> → Präprozessor-Makros (z. B. <code>STD_ON</code> / <code>STD_OFF</code>).\n</li><li><code>IntegerValue</code> / <code>FloatValue</code> / <code>EnumerationValue</code> → Konstanten oder Struct-Initialisierer im ROM-Config-Block (<code>&lt;Module&gt;_PBcfg.c</code> / <code>&lt;Module&gt;_Cfg.h</code>).\n</li><li><code>FunctionNameValue</code> → C-Prototypen-Deklarationen (<code>extern void Fct(void);</code>) sowie Funktionszeiger-Tabellen.\n</li></ul>\n</li></ol>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Trennung von Definition und Wert:</strong> Das Diagramm zeigt ausschließlich <em>Values</em>. Ein <code>ParameterValue</code> besitzt keinen eigenen Datentyp-Definitionskörper, sondern referenziert semantisch eine <code>ParameterDef</code> aus dem BSW-Modul-Manifest (<em>BSW Module Description</em>).\n</li><li><strong>Linker- und Callback-Sicherheit:</strong>\n<ul class=\"fig-list\"><li>Da <code>FunctionNameValue</code> und <code>LinkerSymbolValue</code> rein syntaktisch als XML-Strings gespeichert werden, erfolgt keine statische Typprüfung im ARXML-Schema bezüglich der C-Signatur.\n</li><li>Fehlerhafte Strings (z. B. abweichende Callback-Signaturen oder Tippfehler) führen erst bei der Kompilierung/beim Linken zu Fehlern (<code>unresolved external symbol</code>).\n</li></ul>\n</li><li><strong>Speicherlayout &amp; Initialisierung:</strong>\n<ul class=\"fig-list\"><li>Die Kardinalität <code>*</code> bei <code>+subContainer</code> und <code>+parameterValue</code> bedingt in der BSW-Implementierung entweder dynamische Iteration (Pre-Compile) oder feld-basierte Zeigerstrukturen (Post-Build).\n</li><li><code>EnumerationValue.value</code> ist im Modell als String modelliert; der Codegenerator muss diesen String zwingend auf das zugehörige C-Enum-Literal oder <code>#define</code> abbilden.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-0bc3a77f59c79397", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt der AUTOSAR ECU Configuration Description (Werte-Ebene / <em>Values</em>).\n</li><li><strong>Architektur-Kontext:</strong> Definiert die formale Datenstruktur zur Ablage konkreter Parameterwerte (<code>ParameterValue</code>) innerhalb der Konfigurationsbäume (<code>Container</code>) für AUTOSAR-Basissoftware (BSW), RTE und System-Module. Es bildet die Instanzebene ab, die zur Konfigurationszeit (Design/Generate Time) befüllt und von BSW- und RTE-Codegeneratoren verarbeitet wird.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>Identifiable</code></strong> <em>(Metaklasse/Stereotyp)</em>: Basis-Metaklasse für alle eindeutig adressierbaren Artefakte (stellt u. a. <code>shortName</code> bereit).\n</li><li><strong><code>Container</code></strong> <em>(Spezialisierung von <code>Identifiable</code>)</em>:\n<ul class=\"fig-list\"><li>Strukturelle Kapselung logisch zusammengehöriger Parameter und Unterstrukturen.\n</li><li><strong>Beziehungen:</strong>\n<ul class=\"fig-list\"><li><em>Selbstreferenzielle Komposition:</em> <code>0..1</code> Container enthält <code>*</code> Sub-Container (<code>+subContainer</code>), ausgezeichnet mit dem Stereotyp <code>«splitable»</code>.\n</li><li><em>Komposition zu Werten:</em> <code>1</code> Container aggregiert <code>*</code> Parameterwerte (<code>+parameterValue</code>), ausgezeichnet mit dem Stereotyp <code>«splitable»</code>.\n</li></ul>\n</li></ul>\n</li><li><strong><code>ParameterValue</code></strong> <em>(abstrakte Basisklasse)</em>:\n<ul class=\"fig-list\"><li>Abstrakter Anker für alle typisierten Konfigurationsparameter.\n</li></ul>\n</li><li><strong>Typisierte Ableitungen von <code>ParameterValue</code>:</strong>\n<ul class=\"fig-list\"><li><strong><code>BooleanValue</code></strong>: Attribut <code>+ value: Boolean</code> (repräsentiert logische Schalter, Flags).\n</li><li><strong><code>IntegerValue</code></strong>: Attribut <code>+ value: UnlimitedInteger</code> (ganzzahlige Werte beliebiger Genauigkeit wie Zähler, PDU-IDs, IDs, Puffergrößen).\n</li><li><strong><code>FloatValue</code></strong>: Attribut <code>+ value: Float</code> (Fließkommazahlen für Zeitkonstanten, physikalische Skalierungen).\n</li><li><strong><code>EnumerationValue</code></strong>: Attribut <code>+ value: String</code> (textuelle Repräsentation des ausgewählten Literals).\n</li><li><strong><code>StringValue</code></strong>: Attribut <code>+ value: String</code> (generische Zeichenketten, Pfade, Dateinamen).\n</li></ul>\n</li><li><strong>Spezialisierungskette für Symbol-Referenzen:</strong>\n<ul class=\"fig-list\"><li><strong><code>LinkerSymbolValue</code></strong> <em>(erbt von <code>StringValue</code>)</em>: Spezieller Bezeichner, der zur Link-Zeit gegen ein Symbol im Objektcode auflösbar sein muss.\n</li><li><strong><code>FunctionNameValue</code></strong> <em>(erbt von <code>LinkerSymbolValue</code>)</em>: Repräsentiert explizit einen C-Funktionsnamen (z. B. Entrypoints, Callbacks, Notifier).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Laufzeit-Verhalten:</strong> Nicht zutreffend (statisches Konfigurations-Metamodell).\n</li><li><strong>Toolchain-/Generierungs-Zyklus:</strong>\n<ol class=\"fig-list\"><li><strong>Parsen:</strong> Der Konfigurationsgenerator liest den hierarchischen Container-Baum (<code>Container</code> → <code>subContainer</code>) aus der ARXML ein.\n</li><li><strong>Typauflösung:</strong> Instanzen von <code>ParameterValue</code> werden gegen die korrespondierende Parameter-Definition (<code>ParameterDef</code>) validiert (Wertebereichs- und Typprüfung).\n</li><li><strong>Artefakt-Generierung:</strong> \n<ul class=\"fig-list\"><li><code>BooleanValue</code> → Präprozessor-Makros (z. B. <code>STD_ON</code> / <code>STD_OFF</code>).\n</li><li><code>IntegerValue</code> / <code>FloatValue</code> / <code>EnumerationValue</code> → Konstanten oder Struct-Initialisierer im ROM-Config-Block (<code>&lt;Module&gt;_PBcfg.c</code> / <code>&lt;Module&gt;_Cfg.h</code>).\n</li><li><code>FunctionNameValue</code> → C-Prototypen-Deklarationen (<code>extern void Fct(void);</code>) sowie Funktionszeiger-Tabellen.\n</li></ul>\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Trennung von Definition und Wert:</strong> Das Diagramm zeigt ausschließlich <em>Values</em>. Ein <code>ParameterValue</code> besitzt keinen eigenen Datentyp-Definitionskörper, sondern referenziert semantisch eine <code>ParameterDef</code> aus dem BSW-Modul-Manifest (<em>BSW Module Description</em>).\n</li><li><strong>Aufspaltbarkeit (<code>«splitable»</code>):</strong> Die Aggregationen von <code>parameterValue</code> und <code>subContainer</code> tragen das Stereotyp <code>«splitable»</code>. Damit können Container-Inhalte und Parameterwerte über mehrere physische ARXML-Dateien oder Konfigurationsfragmente verteilt und im Modell zusammengeführt werden.\n</li><li><strong>Wertebereichsabbildung:</strong> Durch den Basistyp <code>UnlimitedInteger</code> für <code>IntegerValue</code> ist das Metamodell nicht auf standardmäßige C-Ganzzahlbreiten beschränkt; die Begrenzung auf zulässige Zieltypen erfolgt über die zugehörige Parameterdefinition.\n</li><li><strong>Linker- und Callback-Sicherheit:</strong> Da <code>FunctionNameValue</code> und <code>LinkerSymbolValue</code> rein syntaktisch als XML-Strings gespeichert werden, obliegt die Namensvalidierung (C-Konformität, Linker-Sichtbarkeit) dem Codegenerator bzw. BSW-Prüfwerkzeug.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-b3559297faf97255", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt der AUTOSAR ECU Configuration Description (Werte-Ebene / <em>Values</em>).\n</li><li><strong>Architektur-Kontext:</strong> Definiert die formale Datenstruktur zur Ablage konkreter Parameterwerte (<code>ParameterValue</code>) innerhalb der Konfigurationsbäume (<code>Container</code>) für AUTOSAR-Basissoftware (BSW), RTE und System-Module. Es bildet die Instanzebene ab, die zur Konfigurationszeit (Design/Generate Time) befüllt und von BSW- und RTE-Codegeneratoren verarbeitet wird.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>Identifiable</code></strong> <em>(Metaklasse/Stereotyp)</em>: Basis-Metaklasse für alle eindeutig adressierbaren Artefakte (stellt u. a. <code>shortName</code> bereit).\n</li><li><strong><code>Container</code></strong> <em>(Spezialisierung von <code>Identifiable</code>)</em>:\n<ul class=\"fig-list\"><li>Strukturelle Kapselung logisch zusammengehöriger Parameter und Unterstrukturen.\n</li><li><strong>Beziehungen:</strong>\n<ul class=\"fig-list\"><li><em>Selbstreferenzielle Komposition:</em> <code>0..1</code> Container enthält <code>*</code> Sub-Container (<code>+subContainer</code>), ausgezeichnet mit dem Stereotyp <code>«splitable»</code>.\n</li><li><em>Komposition zu Werten:</em> <code>1</code> Container aggregiert <code>*</code> Parameterwerte (<code>+parameterValue</code>), ausgezeichnet mit dem Stereotyp <code>«splitable»</code>.\n</li></ul>\n</li></ul>\n</li><li><strong><code>ParameterValue</code></strong> <em>(abstrakte Basisklasse)</em>:\n<ul class=\"fig-list\"><li>Abstrakter Anker für alle typisierten Konfigurationsparameter.\n</li></ul>\n</li><li><strong>Typisierte Ableitungen von <code>ParameterValue</code>:</strong>\n<ul class=\"fig-list\"><li><strong><code>BooleanValue</code></strong>: Attribut <code>+ value: Boolean</code> (repräsentiert logische Schalter, Flags).\n</li><li><strong><code>IntegerValue</code></strong>: Attribut <code>+ value: UnlimitedInteger</code> (ganzzahlige Werte beliebiger Genauigkeit wie Zähler, PDU-IDs, IDs, Puffergrößen).\n</li><li><strong><code>FloatValue</code></strong>: Attribut <code>+ value: Float</code> (Fließkommazahlen für Zeitkonstanten, physikalische Skalierungen).\n</li><li><strong><code>EnumerationValue</code></strong>: Attribut <code>+ value: String</code> (textuelle Repräsentation des ausgewählten Literals).\n</li><li><strong><code>StringValue</code></strong>: Attribut <code>+ value: String</code> (generische Zeichenketten, Pfade, Dateinamen).\n</li></ul>\n</li><li><strong>Spezialisierungskette für Symbol-Referenzen:</strong>\n<ul class=\"fig-list\"><li><strong><code>LinkerSymbolValue</code></strong> <em>(erbt von <code>StringValue</code>)</em>: Spezieller Bezeichner, der zur Link-Zeit gegen ein Symbol im Objektcode auflösbar sein muss.\n</li><li><strong><code>FunctionNameValue</code></strong> <em>(erbt von <code>LinkerSymbolValue</code>)</em>: Repräsentiert explizit einen C-Funktionsnamen (z. B. Entrypoints, Callbacks, Notifier).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Laufzeit-Verhalten:</strong> Nicht zutreffend (statisches Konfigurations-Metamodell).\n</li><li><strong>Toolchain-/Generierungs-Zyklus:</strong>\n<ol class=\"fig-list\"><li><strong>Parsen:</strong> Der Konfigurationsgenerator liest den hierarchischen Container-Baum (<code>Container</code> → <code>subContainer</code>) aus der ARXML ein.\n</li><li><strong>Typauflösung:</strong> Instanzen von <code>ParameterValue</code> werden gegen die korrespondierende Parameter-Definition (<code>ParameterDef</code>) validiert (Wertebereichs- und Typprüfung).\n</li><li><strong>Artefakt-Generierung:</strong> \n<ul class=\"fig-list\"><li><code>BooleanValue</code> → Präprozessor-Makros (z. B. <code>STD_ON</code> / <code>STD_OFF</code>).\n</li><li><code>IntegerValue</code> / <code>FloatValue</code> / <code>EnumerationValue</code> → Konstanten oder Struct-Initialisierer im ROM-Config-Block (<code>&lt;Module&gt;_PBcfg.c</code> / <code>&lt;Module&gt;_Cfg.h</code>).\n</li><li><code>FunctionNameValue</code> → C-Prototypen-Deklarationen (<code>extern void Fct(void);</code>) sowie Funktionszeiger-Tabellen.\n</li></ul>\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Trennung von Definition und Wert:</strong> Das Diagramm zeigt ausschließlich <em>Values</em>. Ein <code>ParameterValue</code> besitzt keinen eigenen Datentyp-Definitionskörper, sondern referenziert semantisch eine <code>ParameterDef</code> aus dem BSW-Modul-Manifest (<em>BSW Module Description</em>).\n</li><li><strong>Aufspaltbarkeit (<code>«splitable»</code>):</strong> Die Aggregationen von <code>parameterValue</code> und <code>subContainer</code> tragen das Stereotyp <code>«splitable»</code>. Damit können Container-Inhalte und Parameterwerte über mehrere physische ARXML-Dateien oder Konfigurationsfragmente verteilt und im Modell zusammengeführt werden.\n</li><li><strong>Wertebereichsabbildung:</strong> Durch den Basistyp <code>UnlimitedInteger</code> für <code>IntegerValue</code> ist das Metamodell nicht auf standardmäßige C-Ganzzahlbreiten beschränkt; die Begrenzung auf zulässige Zieltypen erfolgt über die zugehörige Parameterdefinition.\n</li><li><strong>Linker- und Callback-Sicherheit:</strong> Da <code>FunctionNameValue</code> und <code>LinkerSymbolValue</code> rein syntaktisch als XML-Strings gespeichert werden, obliegt die Namensvalidierung (C-Konformität, Linker-Sichtbarkeit) dem Codegenerator bzw. BSW-Prüfwerkzeug.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-2c75cd220f275a54", "to": "FIG-0bc3a77f59c79397", "fr": "R2.1.20", "tr": "R3.0.7", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Metaklasse <code>IntegerValue</code>: Attributtyp von <code>+ value: Int</code> zu <code>+ value: UnlimitedInteger</code> geändert.\n</li><li>Komposition <code>Container</code> zu <code>ParameterValue</code> (<code>+parameterValue</code>): Stereotyp <code>«splitable»</code> ergänzt.\n</li><li>Selbstreferenzielle Komposition <code>Container</code> zu <code>Container</code> (<code>+subContainer</code>): Stereotyp <code>«splitable»</code> ergänzt.\n</li></ul>"}, {"from": "FIG-0bc3a77f59c79397", "to": "FIG-b3559297faf97255", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Selbstreferenzielle Komposition <code>Container</code> zu <code>Container</code>: Stereotyp <code>«splitable»</code> und Multiplizität <code>0..1</code> von der unteren Kante an das obere Ende der Assoziationslinie verschoben.\n</li><li>Attribute aller Wertekapseln (<code>BooleanValue</code>, <code>IntegerValue</code>, <code>FloatValue</code>, <code>StringValue</code>, <code>EnumerationValue</code>): Leerzeichensetzung beim Typ-Trennzeichen von <code>+ value: &lt;Typ&gt;</code> zu <code>+ value :&lt;Typ&gt;</code> geändert.\n</li></ul>"}]};
